<div class="d-flex justify-content-between align-items-center mb-4"><div><h1 class="h3 mb-1">User management</h1><p class="text-secondary mb-0">Create and manage internal accounts.</p></div><a class="btn btn-primary" href="<?= site_url('admin/users/new') ?>">Create user</a></div><div class="card"><div class="table-responsive"><table class="table table-hover mb-0"><thead><tr><th>Name</th><th>Email</th><th>Department</th><th>Role</th><th>Status</th></tr></thead><tbody><?php foreach ($users as $person): ?><tr><td><a href="<?= site_url('admin/users/' . $person['id']) ?>"><?= esc($person['name']) ?></a></td><td><?= esc($person['email']) ?></td><td><?= esc($person['department']) ?></td><td><?= esc($person['role']) ?></td><td><?= $person['is_active'] ? 'Active' : 'Inactive' ?></td></tr><?php endforeach ?></tbody></table></div></div>
